contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool firstInitReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstInitReverted = true; } else { firstInitReverted = false; }

        uint minAfterFirstInit = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondInitReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondInitReverted = true; } else { secondInitReverted = false; }

        uint minAfterSecondInit = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!firstInitReverted && !secondInitReverted && minAfterFirstInit == minBefore && minAfterSecondInit == minBefore);
    }

    receive() external payable {}
}

