pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val) internal {
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool firstInitReverted;
        try c.Initialized() { firstInitReverted = false; } catch { firstInitReverted = true; }
        uint256 minAfterFirstInit;
        try c.MinSum() returns (uint256 __r) { minAfterFirstInit = __r; } catch { return; }
        bool secondInitReverted;
        try c.Initialized() { secondInitReverted = false; } catch { secondInitReverted = true; }
        uint256 minAfterSecondInit;
        try c.MinSum() returns (uint256 __r) { minAfterSecondInit = __r; } catch { return; }
        assertTrue(!firstInitReverted && !secondInitReverted && minAfterFirstInit == minBefore && minAfterSecondInit == minBefore);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
